turn nil end for i=1,h do local r=rows[i]if type(r)~="string"or#r~=w or not r:match("^%x+$")then return nil end end return rows end local function pictureFile(path)local f=fs.open(path,"r")if not f then return nil end local first=f.readLine()if not first then f.close()return nil end if first:match("^CCWIN2")then f.close()local w,h=first:match("^CCWIN2%s+(%d+)%s+(%d+)")w,h=tonumber(w),tonumber(h)if not picture or not w or not h or w<1 or h<1 or w>MAX_ICON or h>MAX_ICON then return nil end local data=picture.readFile(path,65536)if not data then return nil end local ok,rows=pcall(picture.decode,data)if not ok or type(rows)~="table"then return nil end local out={}for y=1,h do local row=rows[y]if type(row)~="string"then return nil end local line={}for x=1,w do local v=row:byte(x)or 15 if v>15 then v=15 end line[x]=string.format("%x",v)end out[y]=table.concat(line)end return programs.iconRows(out)end local rows={}if first:match("^CCWIN1")then local w=tonumber(first:match("^CCWIN1%s+(%d+)"))local h=tonumber(first:match("^CCWIN1%s+%d+%s+(%d+)"))if not w or not h or w<1 or h<1 or w>MAX_ICON or h>MAX_ICON then f.close()return nil end for _=1,h do local line=f.readLine()if not line then break end local out={}for x=1,math.min(w,math.floor(#line/2))do local v=tonumber(line:sub(x*2-1,x*2),16)or 15 if v>15 then v=15 end out[x]=string.format("%x",v)end rows[#rows+1]=table.concat(out)end else rows[1]=first while true do local line=f.readLine()if not line then break end rows[#rows+1]=line end end f.close()return programs.iconRows(rows)end local function embeddedIcon(path)local f=fs.open(path,"r")if not f then return nil end local rows,reading=nil,false while true do local line=f.readLine()if not line then break end local body=line:match("^%-%-%-?%s*(.*)$")if not body then if reading then break end elseif not reading then if body:lower():match("^icon:%s*$")then reading,rows=true,{}end elseif body:match("^%x+$")then rows[#rows+1]=body else break end end f.close()return programs.iconRow